package literal

import (
	"context"
	"io"

	"github.com/lycaon/lycaon/internal/commandprogram"
	"github.com/lycaon/lycaon/internal/toolcontract"
)

const outputChunkBytes = 32 * 1024

// output meters stdout against stream_bytes before each write and records
// exact source mappings when the endpoint retains them. Generated bytes
// (numbers, headers, notation) never carry a mapping.
type output struct {
	ctx              context.Context
	w                io.Writer
	mappings         commandprogram.SourceMappingRecorder
	maximum, written int64
}

func newOutput(ctx context.Context, w io.Writer, maximum int64) *output {
	if w == nil {
		w = io.Discard
	}
	o := &output{ctx: ctx, w: w, maximum: maximum}
	o.mappings, _ = w.(commandprogram.SourceMappingRecorder)
	return o
}

func (o *output) Write(p []byte) (int, error) {
	if o.maximum > 0 && o.written+int64(len(p)) > o.maximum {
		return 0, limitExceeded("stream_bytes", o.maximum, o.written+int64(len(p)))
	}
	sent := 0
	for len(p) > 0 {
		if err := o.ctx.Err(); err != nil {
			return sent, err
		}
		chunk := p[:min(len(p), outputChunkBytes)]
		n, err := o.w.Write(chunk)
		if n < 0 || n > len(chunk) {
			return sent, io.ErrShortWrite
		}
		sent += n
		o.written += int64(n)
		if err != nil {
			return sent, err
		}
		if n != len(chunk) {
			return sent, io.ErrShortWrite
		}
		p = p[n:]
	}
	return sent, nil
}

func (o *output) text(s string) error {
	_, err := io.WriteString(o, s)
	return err
}

// literal writes bytes taken verbatim from in at offset and, for a pinned
// capture, records them as an exact mapping of that capture.
func (o *output) literal(in *input, p []byte, offset int64) error {
	if len(p) == 0 {
		return nil
	}
	outStart := o.written
	if _, err := o.Write(p); err != nil {
		return err
	}
	if o.mappings == nil || in.pin == nil {
		return nil
	}
	return o.mappings.RecordSourceMapping(toolcontract.StreamSourceMapping{Source: *in.pin, SourceStartByte: offset, SourceEndByte: offset + int64(len(p)), OutputStartByte: outStart, OutputEndByte: o.written})
}
